import javax.swing.*;import java.awt.*;import java.awt.event.*;
public class ConverterNamedInner extends JFrame {JTextField amount=new JTextField(10);JComboBox<String> target=new JComboBox<>(new String[]{"USD","EUR"});JLabel result=new JLabel(" ");ConverterNamedInner(){setLayout(new FlowLayout());JButton b=new JButton("Convert");add(amount);add(target);add(b);add(result);Handler h=new Handler();b.addActionListener(h);amount.addActionListener(h);addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){dispose();}});pack();}private class Handler implements ActionListener{public void actionPerformed(ActionEvent e){try{double v=Double.parseDouble(amount.getText().trim());if(!Double.isFinite(v)||v<0)throw new NumberFormatException();result.setText(String.format("%.2f",v*(target.getSelectedItem().equals("USD")?.012:.011)));JOptionPane.showMessageDialog(ConverterNamedInner.this,result.getText()+" "+target.getSelectedItem(),"Conversion result",JOptionPane.INFORMATION_MESSAGE);}catch(Exception ex){result.setText("Invalid amount");JOptionPane.showMessageDialog(ConverterNamedInner.this,"Invalid amount","Input error",JOptionPane.ERROR_MESSAGE);}}}public static void main(String[]x){SwingUtilities.invokeLater(()->new ConverterNamedInner().setVisible(true));}}
